{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "B"
      ],
      "content": "Hey, I'm curious — do you have any squares you can share? I need one for my order and I'm thinking we could trade something back. What do you think?"
    }
  },
  "rationale": "I need a square to fulfill my order, and since B has the specialty square, they're a natural partner. Starting a casual conversation opens up a trade opportunity without pressure."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "A"
      ],
      "content": "Hey, I noticed you're producing circles. Since I need a circle for my order, I'm thinking of buying one from you. How about a price of $25? I can pay that if it works for you."
    }
  },
  "rationale": "I need a circle to fulfill my order, and A has the specialty shape. Offering a fair price of $25 balances cost and value, and it's within the trade range."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "C"
      ],
      "content": "Hey, I'm working on getting a triangle for my order. Since you're the one who makes triangles, I was wondering if you'd be open to trading a circle for one of yours? I can offer $30 for it."
    }
  },
  "rationale": "I need a triangle to fulfill my order, and C has the specialty shape. A direct message to propose a fair trade makes sense, given my limited production capacity and the need to act strategically."
}

